SELECT "sk_customerid", "sk_accountid", "sk_dateid", "cash", "batchid" FROM (SELECT TRY_CAST((CAST(ct.CT_CA_ID AS INT)) AS INT) AS "sk_customerid", TRY_CAST((CAST(ct.CT_CA_ID AS INT)) AS INT) AS "sk_accountid", TRY_CAST((CAST(STRFTIME(ct.CT_DTS, '%Y%m%d') AS INT)) AS INT) AS "sk_dateid", TRY_CAST((CAST(ct.CT_AMT AS DECIMAL(15, 2))) AS DECIMAL(15, 2)) AS "cash", TRY_CAST((CAST(NULL AS DECIMAL(5))) AS DECIMAL(5)) AS "batchid" FROM "Source"."CashTransaction" AS ct);
